    branch1 = _mm256_fmsub_ps(branch1, _mm256_set1_ps(1.1115F), _mm256_set1_ps(0.1115F));
    __m256 res = _mm256_blendv_ps(branch0, branch1, _mm256_cmp_ps(pix_abs, _mm256_set1_ps(0.0228F), _CMP_GE_OQ));
    return _mm256_or_ps(_mm256_andnot_ps(v_abs, pix), res);
