static __m256 simd_linear_to_smpte2084_ps(__m256 pix) {
    const __m256 v_abs = _mm256_castsi256_ps(_mm256_set1_epi32(0x7FFFFFFF));
    __m256 v_pow = simd_pow_ps_pd(_mm256_and_ps(pix, v_abs), _mm256_set1_pd(0.1593017578125));
    __m256 v_nom = _mm256_fmadd_ps(v_pow, _mm256_set1_ps(18.8515625F), _mm256_set1_ps(0.8359375F));
    __m256 v_den = _mm256_fmadd_ps(v_pow, _mm256_set1_ps(18.6875F), _mm256_set1_ps(1.0F));
    __m256 res = simd_pow_ps_pd(_mm256_div_ps(v_nom, v_den), _mm256_set1_pd(78.84375));
    return _mm256_or_ps(_mm256_andnot_ps(v_abs, pix), res);
}

