    acc = _mm256_fmadd_pd(temp0, temp1, acc);
    temp0 = _mm256_sub_pd(_mm256_cvtps_pd(_mm256_extractf128_ps(row0_6, 0)), mean0);
    temp1 = _mm256_sub_pd(_mm256_cvtps_pd(_mm256_extractf128_ps(row1_6, 0)), mean1);
