static void transpose_block_into_buf_epi8(
    const uint8_t *restrict srcp, uint8_t *restrict dstp, ptrdiff_t stride, int src_w
) {
    for (int x = 0; x < src_w; x += 32) {
        __m256i pix0 = _mm256_load_si256((const __m256i *)(srcp + stride * 0));
        __m256i pix1 = _mm256_load_si256((const __m256i *)(srcp + stride * 1));
        __m256i pix2 = _mm256_load_si256((const __m256i *)(srcp + stride * 2));
        __m256i pix3 = _mm256_load_si256((const __m256i *)(srcp + stride * 3));
        __m256i pix4 = _mm256_load_si256((const __m256i *)(srcp + stride * 4));
        __m256i pix5 = _mm256_load_si256((const __m256i *)(srcp + stride * 5));
        __m256i pix6 = _mm256_load_si256((const __m256i *)(srcp + stride * 6));
        __m256i pix7 = _mm256_load_si256((const __m256i *)(srcp + stride * 7));
        SIMD_TRANSPOSE32X8_EPI8(pix0, pix1, pix2, pix3, pix4, pix5, pix6, pix7);
        _mm256_store_si256((__m256i *)(dstp + 0), pix0);
        _mm256_store_si256((__m256i *)(dstp + 32), pix1);
        _mm256_store_si256((__m256i *)(dstp + 64), pix2);
        _mm256_store_si256((__m256i *)(dstp + 96), pix3);
        _mm256_store_si256((__m256i *)(dstp + 128), pix4);
        _mm256_store_si256((__m256i *)(dstp + 160), pix5);
        _mm256_store_si256((__m256i *)(dstp + 192), pix6);
        _mm256_store_si256((__m256i *)(dstp + 224), pix7);
        srcp += 32;
        dstp += 256;
    }
}

