static void remove_grain_std_8(
    remove_grain_mode_func mode, const void *restrict srcp, void *restrict dstp,
    int src_w, int src_h, ptrdiff_t stride
) {
    const uint8_t *restrict ptrs = srcp;
    uint8_t *restrict ptrd = dstp;
    int tail = src_w % 32;
    int mod32_w = tail ? src_w - tail : src_w - 32 - tail;
    
    for (int x = 0; x < src_w; x += 32) {
        _mm256_store_si256((__m256i *)(ptrd + x), _mm256_load_si256((const __m256i *)(ptrs + x)));
    }
    ptrs += stride;
    ptrd += stride;
    for (int y = 1; y < src_h - 1; y++) {
        ptrd[0] = ptrs[0];
        if (src_w != 34) mode(ptrs, ptrd, stride, 1);
        for (int x = 32; x < mod32_w; x += 32) mode(ptrs, ptrd, stride, x);
        if (tail != 1) mode(ptrs, ptrd, stride, src_w - 33);
        ptrd[src_w - 1] = ptrs[src_w - 1];
        ptrs += stride;
        ptrd += stride;
    }
    for (int x = 0; x < src_w; x += 32) {
        _mm256_store_si256((__m256i *)(ptrd + x), _mm256_load_si256((const __m256i *)(ptrs + x)));
    }
}

