        temp0 = _mm256_max_ps(_mm256_max_ps(_mm256_max_ps(temp0, pix1_1), pix1_2), pix2_0);
        temp1 = _mm256_min_ps(_mm256_min_ps(_mm256_min_ps(temp1, pix1_1), pix1_2), pix2_0);
        temp0 = _mm256_max_ps(_mm256_max_ps(temp0, pix2_1), pix2_2);
