        for (x = 32; x < mod32_w; x += 32) {
            pix0_0 = _mm256_loadu_si256((const __m256i *)(ptrs - stride + x - 1));
            pix0_1 = _mm256_loadu_si256((const __m256i *)(ptrs - stride + x));
            pix0_2 = _mm256_loadu_si256((const __m256i *)(ptrs - stride + x + 1));
            pix1_0 = _mm256_loadu_si256((const __m256i *)(ptrs + x - 1));
            pix1_2 = _mm256_loadu_si256((const __m256i *)(ptrs + x + 1));
            pix2_0 = _mm256_loadu_si256((const __m256i *)(ptrs + stride + x - 1));
            pix2_1 = _mm256_loadu_si256((const __m256i *)(ptrs + stride + x));
            pix2_2 = _mm256_loadu_si256((const __m256i *)(ptrs + stride + x + 1));
            acc0 = _mm256_unpacklo_epi8(pix0_0, zero);
            acc1 = _mm256_unpackhi_epi8(pix0_0, zero);
            acc2 = _mm256_unpacklo_epi8(pix0_0, zero);
            acc3 = _mm256_unpackhi_epi8(pix0_0, zero);
            acc0 = _mm256_add_epi16(acc0, _mm256_slli_epi16(_mm256_unpacklo_epi8(pix0_1, zero), 1));
            acc1 = _mm256_add_epi16(acc1, _mm256_slli_epi16(_mm256_unpackhi_epi8(pix0_1, zero), 1));
            acc2 = _mm256_sub_epi16(acc2, _mm256_unpacklo_epi8(pix0_2, zero));
            acc3 = _mm256_sub_epi16(acc3, _mm256_unpackhi_epi8(pix0_2, zero));
            acc0 = _mm256_add_epi16(acc0, _mm256_unpacklo_epi8(pix0_2, zero));
            acc1 = _mm256_add_epi16(acc1, _mm256_unpackhi_epi8(pix0_2, zero));
            acc2 = _mm256_add_epi16(acc2, _mm256_slli_epi16(_mm256_unpacklo_epi8(pix1_0, zero), 1));
            acc3 = _mm256_add_epi16(acc3, _mm256_slli_epi16(_mm256_unpackhi_epi8(pix1_0, zero), 1));
            acc0 = _mm256_sub_epi16(acc0, _mm256_unpacklo_epi8(pix2_0, zero));
            acc1 = _mm256_sub_epi16(acc1, _mm256_unpackhi_epi8(pix2_0, zero));
            acc2 = _mm256_sub_epi16(acc2, _mm256_slli_epi16(_mm256_unpacklo_epi8(pix1_2, zero), 1));
            acc3 = _mm256_sub_epi16(acc3, _mm256_slli_epi16(_mm256_unpackhi_epi8(pix1_2, zero), 1));
            acc0 = _mm256_sub_epi16(acc0, _mm256_slli_epi16(_mm256_unpacklo_epi8(pix2_1, zero), 1));
            acc1 = _mm256_sub_epi16(acc1, _mm256_slli_epi16(_mm256_unpackhi_epi8(pix2_1, zero), 1));
            acc2 = _mm256_add_epi16(acc2, _mm256_unpacklo_epi8(pix2_0, zero));
            acc3 = _mm256_add_epi16(acc3, _mm256_unpackhi_epi8(pix2_0, zero));
            acc0 = _mm256_sub_epi16(acc0, _mm256_unpacklo_epi8(pix2_2, zero));
            acc1 = _mm256_sub_epi16(acc1, _mm256_unpackhi_epi8(pix2_2, zero));
            acc2 = _mm256_sub_epi16(acc2, _mm256_unpacklo_epi8(pix2_2, zero));
            acc3 = _mm256_sub_epi16(acc3, _mm256_unpackhi_epi8(pix2_2, zero));
            acc0 = _mm256_max_epi16(_mm256_abs_epi16(acc0), _mm256_abs_epi16(acc2));
            acc1 = _mm256_max_epi16(_mm256_abs_epi16(acc1), _mm256_abs_epi16(acc3));
            acc0 = _mm256_packus_epi16(acc0, acc1);
            _mm256_stream_si256((__m256i *)(ptrd + x), acc0);
        }
        
        pix0_0 = _mm256_loadu_si256((const __m256i *)(ptrs - stride + x - 1));
        pix0_1 = _mm256_loadu_si256((const __m256i *)(ptrs - stride + x));
        pix1_0 = _mm256_loadu_si256((const __m256i *)(ptrs + x - 1));
        pix1_1 = _mm256_loadu_si256((const __m256i *)(ptrs + x));
