    acc0 = _mm256_sub_epi32(acc0, _mm256_unpacklo_epi16(pix1_2, zero));
    acc1 = _mm256_sub_epi32(acc1, _mm256_unpackhi_epi16(pix1_2, zero));
    acc0 = _mm256_sub_epi32(acc0, _mm256_unpacklo_epi16(pix1_1, zero));
    acc1 = _mm256_sub_epi32(acc1, _mm256_unpackhi_epi16(pix1_1, zero));
    acc0 = _mm256_sub_epi32(acc0, _mm256_unpacklo_epi16(pix1_2, zero));
    acc1 = _mm256_sub_epi32(acc1, _mm256_unpackhi_epi16(pix1_2, zero));
    acc2 = _mm256_add_epi32(_mm256_unpacklo_epi16(pix0_0, zero), _mm256_unpacklo_epi16(pix0_1, zero));
    acc3 = _mm256_add_epi32(_mm256_unpackhi_epi16(pix0_0, zero), _mm256_unpackhi_epi16(pix0_1, zero));
    acc2 = _mm256_add_epi32(acc2, _mm256_unpacklo_epi16(pix0_2, zero));
    acc3 = _mm256_add_epi32(acc3, _mm256_unpackhi_epi16(pix0_2, zero));
    acc2 = _mm256_sub_epi32(acc2, _mm256_unpacklo_epi16(pix1_0, zero));
    acc3 = _mm256_sub_epi32(acc3, _mm256_unpackhi_epi16(pix1_0, zero));
    acc2 = _mm256_sub_epi32(acc2, _mm256_unpacklo_epi16(pix1_1, zero));
    acc3 = _mm256_sub_epi32(acc3, _mm256_unpackhi_epi16(pix1_1, zero));
    acc2 = _mm256_sub_epi32(acc2, _mm256_unpacklo_epi16(pix1_2, zero));
    acc3 = _mm256_sub_epi32(acc3, _mm256_unpackhi_epi16(pix1_2, zero));
    acc4 = _mm256_add_epi32(_mm256_unpacklo_epi16(pix0_0, zero), _mm256_unpacklo_epi16(pix1_0, zero));
    acc5 = _mm256_add_epi32(_mm256_unpackhi_epi16(pix0_0, zero), _mm256_unpackhi_epi16(pix1_0, zero));
    acc4 = _mm256_add_epi32(acc4, _mm256_unpacklo_epi16(pix1_0, zero));
    acc5 = _mm256_add_epi32(acc5, _mm256_unpackhi_epi16(pix1_0, zero));
    acc4 = _mm256_sub_epi32(acc4, _mm256_unpacklo_epi16(pix0_2, zero));
    acc5 = _mm256_sub_epi32(acc5, _mm256_unpackhi_epi16(pix0_2, zero));
    acc4 = _mm256_sub_epi32(acc4, _mm256_unpacklo_epi16(pix1_2, zero));
    acc5 = _mm256_sub_epi32(acc5, _mm256_unpackhi_epi16(pix1_2, zero));
    acc4 = _mm256_sub_epi32(acc4, _mm256_unpacklo_epi16(pix1_2, zero));
    acc5 = _mm256_sub_epi32(acc5, _mm256_unpackhi_epi16(pix1_2, zero));
    acc6 = _mm256_add_epi32(_mm256_unpacklo_epi16(pix1_0, zero), _mm256_unpacklo_epi16(pix1_0, zero));
    acc7 = _mm256_add_epi32(_mm256_unpackhi_epi16(pix1_0, zero), _mm256_unpackhi_epi16(pix1_0, zero));
    acc6 = _mm256_add_epi32(acc6, _mm256_unpacklo_epi16(pix1_1, zero));
    acc7 = _mm256_add_epi32(acc7, _mm256_unpackhi_epi16(pix1_1, zero));
    acc6 = _mm256_sub_epi32(acc6, _mm256_unpacklo_epi16(pix0_1, zero));
    acc7 = _mm256_sub_epi32(acc7, _mm256_unpackhi_epi16(pix0_1, zero));
    acc6 = _mm256_sub_epi32(acc6, _mm256_unpacklo_epi16(pix0_2, zero));
    acc7 = _mm256_sub_epi32(acc7, _mm256_unpackhi_epi16(pix0_2, zero));
    acc6 = _mm256_sub_epi32(acc6, _mm256_unpacklo_epi16(pix1_2, zero));
    acc7 = _mm256_sub_epi32(acc7, _mm256_unpackhi_epi16(pix1_2, zero));
    acc0 = _mm256_max_epi32(_mm256_abs_epi32(acc0), _mm256_abs_epi32(acc2));
    acc0 = _mm256_max_epi32(_mm256_max_epi32(acc0, _mm256_abs_epi32(acc4)), _mm256_abs_epi32(acc6));
    acc1 = _mm256_max_epi32(_mm256_abs_epi32(acc1), _mm256_abs_epi32(acc3));
    acc1 = _mm256_max_epi32(_mm256_max_epi32(acc1, _mm256_abs_epi32(acc5)), _mm256_abs_epi32(acc7));
    acc0 = _mm256_packus_epi32(acc0, acc1);
    _mm256_stream_si256((__m256i *)(ptrd + x), acc0);
