        pix1_1 = _mm256_loadu_ps(ptrs);
        pix1_2 = _mm256_loadu_ps(ptrs + 1);
        pix2_1 = _mm256_loadu_ps(ptrs + stride);
        pix2_2 = _mm256_loadu_ps(ptrs + stride + 1);
        pix0_0 = _mm256_permutevar8x32_ps(pix0_1, left_idx);
