        pix2_0 = _mm256_permutevar8x32_ps(pix2_1, left_idx);
        acc0 = _mm256_add_ps(pix0_0, _mm256_xor_ps(pix2_2, v_abs));
        acc0 = _mm256_add_ps(acc0, _mm256_add_ps(pix0_1, _mm256_xor_ps(pix2_1, v_abs)));
        acc0 = _mm256_add_ps(acc0, _mm256_add_ps(pix1_0, _mm256_xor_ps(pix1_2, v_abs)));
        acc1 = _mm256_add_ps(pix0_0, _mm256_xor_ps(pix2_2, v_abs));
        acc1 = _mm256_add_ps(acc1, _mm256_add_ps(pix0_1, _mm256_xor_ps(pix2_1, v_abs)));
        acc1 = _mm256_add_ps(acc1, _mm256_add_ps(pix0_2, _mm256_xor_ps(pix2_0, v_abs)));
        acc2 = _mm256_add_ps(pix0_0, _mm256_xor_ps(pix2_2, v_abs));
        acc2 = _mm256_add_ps(acc2, _mm256_add_ps(pix1_0, _mm256_xor_ps(pix1_2, v_abs)));
        acc2 = _mm256_add_ps(acc2, _mm256_add_ps(pix2_0, _mm256_xor_ps(pix0_2, v_abs)));
        acc3 = _mm256_add_ps(pix1_0, _mm256_xor_ps(pix1_2, v_abs));
        acc3 = _mm256_add_ps(acc3, _mm256_add_ps(pix2_0, _mm256_xor_ps(pix0_2, v_abs)));
