        pix0_0 = _mm256_loadu_ps(ptrs - stride + x - 1);
        pix0_1 = _mm256_loadu_ps(ptrs - stride + x);
        pix0_2 = _mm256_loadu_ps(ptrs - stride + x + 1);
        pix1_0 = _mm256_loadu_ps(ptrs + x - 1);
        pix1_1 = _mm256_loadu_ps(ptrs + x);
        pix1_2 = _mm256_loadu_ps(ptrs + x + 1);
        acc0 = _mm256_add_ps(pix0_0, _mm256_xor_ps(pix1_2, v_abs));
        acc0 = _mm256_add_ps(acc0, _mm256_add_ps(pix0_1, _mm256_xor_ps(pix1_1, v_abs)));
        acc0 = _mm256_add_ps(acc0, _mm256_add_ps(pix1_0, _mm256_xor_ps(pix1_2, v_abs)));
        acc1 = _mm256_add_ps(pix0_0, _mm256_xor_ps(pix1_2, v_abs));
        acc1 = _mm256_add_ps(acc1, _mm256_add_ps(pix0_1, _mm256_xor_ps(pix1_1, v_abs)));
        acc1 = _mm256_add_ps(acc1, _mm256_add_ps(pix0_2, _mm256_xor_ps(pix1_0, v_abs)));
        acc2 = _mm256_add_ps(pix0_0, _mm256_xor_ps(pix1_2, v_abs));
        acc2 = _mm256_add_ps(acc2, _mm256_add_ps(pix1_0, _mm256_xor_ps(pix1_2, v_abs)));
        acc2 = _mm256_add_ps(acc2, _mm256_add_ps(pix1_0, _mm256_xor_ps(pix0_2, v_abs)));
        acc3 = _mm256_add_ps(pix1_0, _mm256_xor_ps(pix1_2, v_abs));
        acc3 = _mm256_add_ps(acc3, _mm256_add_ps(pix1_0, _mm256_xor_ps(pix0_2, v_abs)));
        acc3 = _mm256_add_ps(acc3, _mm256_add_ps(pix1_1, _mm256_xor_ps(pix0_1, v_abs)));
        acc0 = _mm256_max_ps(_mm256_andnot_ps(v_abs, acc0), _mm256_andnot_ps(v_abs, acc1));
        acc0 = _mm256_max_ps(acc0, _mm256_max_ps(_mm256_andnot_ps(v_abs, acc2), _mm256_andnot_ps(v_abs, acc3)));
