    acc3 = _mm256_add_epi16(acc3, _mm256_unpackhi_epi8(pix2_0, zero));
    acc4 = _mm256_add_epi16(_mm256_unpacklo_epi8(pix2_0, zero), _mm256_unpacklo_epi8(pix2_1, zero));
    acc5 = _mm256_add_epi16(_mm256_unpackhi_epi8(pix2_0, zero), _mm256_unpackhi_epi8(pix2_1, zero));
