        temp0 = _mm256_add_epi16(_mm256_add_epi16(acc0, acc4), _mm256_unpacklo_epi8(pix1_0, zero));
        temp1 = _mm256_add_epi16(_mm256_add_epi16(acc1, acc5), _mm256_unpackhi_epi8(pix1_0, zero));
        temp0 = _mm256_mullo_epi16(_mm256_add_epi16(temp0, _mm256_unpacklo_epi8(pix1_2, zero)), v_m3);
        temp1 = _mm256_mullo_epi16(_mm256_add_epi16(temp1, _mm256_unpackhi_epi8(pix1_2, zero)), v_m3);
        max0 = _mm256_max_epi16(_mm256_max_epi16(acc0, acc2), _mm256_max_epi16(acc4, acc6));
        max1 = _mm256_max_epi16(_mm256_max_epi16(acc1, acc3), _mm256_max_epi16(acc5, acc7));
        min0 = _mm256_min_epi16(_mm256_min_epi16(acc0, acc2), _mm256_min_epi16(acc4, acc6));
