        acc5 = _mm256_add_ps(acc1, pix2_1);
        acc1 = _mm256_add_ps(acc1, pix0_0);
        acc2 = _mm256_add_ps(pix2_1, pix2_2);
        acc6 = _mm256_add_ps(acc2, pix1_2);
        acc2 = _mm256_add_ps(acc2, pix2_0);
        acc3 = _mm256_add_ps(pix0_2, pix1_2);
        acc7 = _mm256_add_ps(acc3, pix0_1);
        acc3 = _mm256_add_ps(acc3, pix2_2);
        temp = _mm256_mul_ps(_mm256_add_ps(_mm256_add_ps(_mm256_add_ps(pix1_0, pix1_2), acc0), acc2), v_m3);
        amax = _mm256_max_ps(_mm256_max_ps(acc0, acc1), _mm256_max_ps(acc2, acc3));
        amax = _mm256_max_ps(amax, _mm256_max_ps(_mm256_max_ps(acc4, acc5), _mm256_max_ps(acc6, acc7)));
        amin = _mm256_min_ps(_mm256_min_ps(acc0, acc1), _mm256_min_ps(acc2, acc3));
        amin = _mm256_min_ps(amin, _mm256_min_ps(_mm256_min_ps(acc4, acc5), _mm256_min_ps(acc6, acc7)));
        amax = _mm256_and_ps(_mm256_fmadd_ps(amax, v_p8, temp), v_abs);
        amin = _mm256_and_ps(_mm256_fmadd_ps(amin, v_p8, temp), v_abs);
